func (requestLimitsCodec) validateConfigs(ctx context.Context, configs types.Object, diagnostics diag.Diagnostics) diag.Diagnostics {
	if configs.IsNull() || configs.IsUnknown() {
		return diagnostics
	}
	var values requestLimitsConfigsModel
	diagnostics.Append(configs.As(ctx, &values, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return diagnostics
	}
	diagnostics.Append(requestLimitsValidateConfiguredCrossFields(values)...)
	if !values.ContentLengthAction.IsNull() && !values.ContentLengthAction.IsUnknown() && !requestLimitsConfigContentLengthActionValid(values.ContentLengthAction.ValueString()) {
		diagnostics.AddError("Invalid request limits content_length_action", "content_length_action must be one of alert, alert_deny, deny_no_log.")
	}
	if !values.HeaderLineNumAction.IsNull() && !values.HeaderLineNumAction.IsUnknown() && !requestLimitsConfigHeaderLineNumActionValid(values.HeaderLineNumAction.ValueString()) {
		diagnostics.AddError("Invalid request limits header_line_num_action", "header_line_num_action must be one of alert, alert_deny, deny_no_log.")
	}
	if !values.Http2MaxReqAction.IsNull() && !values.Http2MaxReqAction.IsUnknown() && !requestLimitsConfigHttp2MaxReqActionValid(values.Http2MaxReqAction.ValueString()) {
		diagnostics.AddError("Invalid request limits http2_max_req_action", "http2_max_req_action must be one of alert, alert_deny, block_period, deny_no_log.")
	}
	if !values.Http2RstAction.IsNull() && !values.Http2RstAction.IsUnknown() && !requestLimitsConfigHttp2RstActionValid(values.Http2RstAction.ValueString()) {
		diagnostics.AddError("Invalid request limits http2_rst_action", "http2_rst_action must be one of alert, alert_deny, block_period, deny_no_log.")
	}
	if !values.HttpHeaderAction.IsNull() && !values.HttpHeaderAction.IsUnknown() && !requestLimitsConfigHttpHeaderActionValid(values.HttpHeaderAction.ValueString()) {
		diagnostics.AddError("Invalid request limits http_header_action", "http_header_action must be one of alert, alert_deny, deny_no_log.")
	}
	if !values.HttpParamAction.IsNull() && !values.HttpParamAction.IsUnknown() && !requestLimitsConfigHttpParamActionValid(values.HttpParamAction.ValueString()) {
		diagnostics.AddError("Invalid request limits http_param_action", "http_param_action must be one of alert, alert_deny, deny_no_log.")
	}
	if !values.HttpReqAction.IsNull() && !values.HttpReqAction.IsUnknown() && !requestLimitsConfigHttpReqActionValid(values.HttpReqAction.ValueString()) {
		diagnostics.AddError("Invalid request limits http_req_action", "http_req_action must be one of alert, alert_deny, deny_no_log.")
	}
	if !values.OthersAction.IsNull() && !values.OthersAction.IsUnknown() && !requestLimitsConfigOthersActionValid(values.OthersAction.ValueString()) {
		diagnostics.AddError("Invalid request limits others_action", "others_action must be one of alert, alert_deny, deny_no_log.")
	}
	diagnostics.Append(requestLimitsValidateConfiguredAllowMethods(ctx, values.AllowMethods)...)
	return diagnostics
}
func requestLimitsValidateConfiguredCrossFields(values requestLimitsConfigsModel) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if !values.RgMinSettingInitialWindowSize.IsNull() && !values.RgMinSettingInitialWindowSize.IsUnknown() && !values.RgMaxSettingInitialWindowSize.IsNull() && !values.RgMaxSettingInitialWindowSize.IsUnknown() && (values.RgMinSettingInitialWindowSize.ValueInt64() >= values.RgMaxSettingInitialWindowSize.ValueInt64()) {
		diagnostics.AddError("Invalid request limits cross-field configuration", "rg_min_setting_initial_window_size must be less than rg_max_setting_initial_window_size.")
	}
	return diagnostics
}

func requestLimitsValidateDecodedCrossFields(values requestLimitsScalars) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if values.RgMinSettingInitialWindowSize >= values.RgMaxSettingInitialWindowSize {
		diagnostics.AddError("Malformed request limits result", "The successful API result violated the cross-field rule: rg_min_setting_initial_window_size must be less than rg_max_setting_initial_window_size.")
	}
	return diagnostics
}

