func (requestLimitsCodec) ValidateResult(ctx context.Context, result client.WAFModuleResult, ownership wafmodule.OwnershipContext) diag.Diagnostics {
	_, diagnostics := requestLimitsDecodeScalars(result)
	owned, ownershipDiagnostics := requestLimitsOwnership(ctx, result.Template, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() {
		return diagnostics
	}
	if owned.AllowMethods {
		_, itemDiagnostics := requestLimitsDecodeAllowMethods(result.Configs["allow_methods"])
		diagnostics.Append(itemDiagnostics...)
	}
	return diagnostics
}

