func requestLimitsOwnership(ctx context.Context, template bool, ownership wafmodule.OwnershipContext) (requestLimitsOwnershipSet, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if template {
		return requestLimitsOwnershipSet{AllowMethods: false}, diagnostics
	}
	if ownership.Source == wafmodule.OwnershipImported {
		return requestLimitsOwnershipSet{AllowMethods: true}, diagnostics
	}
	configsValue, ownershipDiagnostics := wafmodule.OwnershipConfigs(ctx, ownership)
	diagnostics.Append(ownershipDiagnostics...)
	if diagnostics.HasError() || configsValue.IsNull() {
		return requestLimitsOwnershipSet{AllowMethods: false}, diagnostics
	}
	if configsValue.IsUnknown() {
		diagnostics.AddError("Unknown request limits ownership", "The configs ownership state was unknown while flattening.")
		return requestLimitsOwnershipSet{AllowMethods: false}, diagnostics
	}
	var configs requestLimitsConfigsModel
	diagnostics.Append(configsValue.As(ctx, &configs, basetypes.ObjectAsOptions{})...)
	return requestLimitsOwnershipSet{AllowMethods: !configs.AllowMethods.IsNull()}, diagnostics
}
