func requestLimitsJSONNull(raw json.RawMessage) bool {
	return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
}

// RejectItemNullUnlessNullable reports a malformed-result diagnostic when a
// collection-item field is present in the remote response as an explicit JSON
// null but the pinned schema does not mark the field nullable. A missing key
// is not rejected here (optional omission is handled by the decode helpers).
func requestLimitsRejectItemNullUnlessNullable(object map[string]json.RawMessage, key string, allowNull bool, location string, diagnostics *diag.Diagnostics) {
	raw, ok := object[key]
	if !ok {
		return
	}
	if requestLimitsJSONNull(raw) && !allowNull {
		diagnostics.AddError("Malformed request limits result", location+" "+key+" was null, which the pinned schema does not mark nullable.")
	}
}
func requestLimitsValidateConfiguredAllowMethods(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var model struct {
		Items types.List `tfsdk:"item"`
	}
	diagnostics.Append(wrapper.As(ctx, &model, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || model.Items.IsNull() || model.Items.IsUnknown() {
		return diagnostics
	}
	var items []allowMethodsItemModel
	diagnostics.Append(model.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("allow_methods item %d", index+1)
		if item.Method.IsNull() {
			diagnostics.AddError("Invalid request limits allow_methods", location+" method is required.")
		} else if !item.Method.IsUnknown() && !requestLimitsAllowMethodsValid(item.Method.ValueString()) {
			diagnostics.AddError("Invalid request limits allow_methods", location+" method must be one of connect, delete, get, head, options, others, patch, post, put, rpc, trace, webdav.")
		}
	}
	return diagnostics
}

func requestLimitsBuildConfiguredAllowMethods(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (allowMethodsOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return allowMethodsOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown request limits allow_methods", "The allow_methods ownership wrapper must be known during apply.")
		return allowMethodsOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown request limits allow_methods", "The planned allow_methods ownership wrapper must be known during apply.")
		return allowMethodsOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper struct {
		Items types.List `tfsdk:"item"`
	}
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return allowMethodsOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown request limits allow_methods", "The allow_methods item blocks must be known during apply.")
		return allowMethodsOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return allowMethodsOwnedList{Set: true, Items: []string{}}, diagnostics
	}
	var configItems, planItems []allowMethodsItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid request limits allow_methods", "The planned item list unexpectedly became null.")
		}
		return allowMethodsOwnedList{Set: true, Items: []string{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return allowMethodsOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid request limits allow_methods", "Configured and planned item counts differ.")
		return allowMethodsOwnedList{}, diagnostics
	}
	items := make([]string, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("allow_methods item %d", index+1)
		if configuredItem.Method.IsNull() {
			diagnostics.AddError("Invalid request limits allow_methods", "The required "+location+" method is null.")
			continue
		}
		value := ""
		if configuredItem.Method.IsUnknown() {
			if plannedItem.Method.IsNull() || plannedItem.Method.IsUnknown() {
				diagnostics.AddError("Unknown request limits allow_methods", "The configured "+location+" method is still unknown during apply.")
				continue
			}
			value = plannedItem.Method.ValueString()
		} else {
			value = configuredItem.Method.ValueString()
		}
		if !requestLimitsAllowMethodsValid(value) {
			diagnostics.AddError("Invalid request limits allow_methods", location+" method must be one of connect, delete, get, head, options, others, patch, post, put, rpc, trace, webdav.")
		}
		items = append(items, value)
	}
	return allowMethodsOwnedList{Set: true, Items: items}, diagnostics
}

func requestLimitsDecodeAllowMethods(raw json.RawMessage) ([]string, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		diagnostics.AddError("Malformed request limits result", "The successful API result did not contain the required allow_methods array.")
		return nil, diagnostics
	}
	if requestLimitsJSONNull(raw) {
		diagnostics.AddError("Malformed request limits result", "The successful API result contained null allow_methods instead of an array.")
		return nil, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed request limits result", "The successful API result contained a non-array allow_methods value.")
		return nil, diagnostics
	}
	items := make([]string, 0, len(rawItems))
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("allow_methods item %d", position+1)
		if requestLimitsJSONNull(rawItem) {
			diagnostics.AddError("Malformed request limits result", location+" was null instead of a string.")
			continue
		}
		var value string
		if err := json.Unmarshal(rawItem, &value); err != nil {
			diagnostics.AddError("Malformed request limits result", location+" was not a string.")
			continue
		}
		if !requestLimitsAllowMethodsValid(value) {
			diagnostics.AddError("Malformed request limits result", location+" was not one of connect, delete, get, head, options, others, patch, post, put, rpc, trace, webdav.")
			continue
		}
		items = append(items, value)
	}
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return items, diagnostics
}

func requestLimitsAllowMethodsWrapperValue(items []string) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	elements := make([]attr.Value, 0, len(items))
	for _, item := range items {
		object, objectDiagnostics := types.ObjectValue(allowMethodsItemAttributeTypes, map[string]attr.Value{"method": types.StringValue(item)})
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: allowMethodsItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(allowMethodsWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
